import { getAllProducts } from '@/lib/db';
import { cacheTag, revalidateTag } from 'next/cache';

// Child component that fetches product data
async function ProductList() {
  'use cache';
  cacheTag('products');

  const products = await getAllProducts();

  return (
    <div className="p-4 border rounded-lg shadow-sm">
      <h2 className="text-xl font-semibold mb-4">Product List</h2>
      <ul className="space-y-2">
        {products.map((product: any) => (
          <li key={product.id} className="flex justify-between items-center p-2 bg-gray-50 rounded">
            <span>{product.name}</span>
            <span className="font-mono">${product.price}</span>
          </li>
        ))}
      </ul>
      <div className="mt-4 text-xs text-gray-500">
        Last fetched: {new Date().toLocaleTimeString()}
      </div>
    </div>
  );
}

export default function Page() {
  // Inline server action to invalidate cache
  async function invalidateProducts() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div className="container mx-auto p-8 max-w-2xl">
      <h1 className="text-3xl font-bold mb-8">Product Management</h1>

      <div className="space-y-8">
        <ProductList />

        <div className="p-4 border rounded-lg bg-gray-50">
          <h3 className="text-lg font-medium mb-2">Cache Control</h3>
          <p className="text-sm text-gray-600 mb-4">
            Clicking the button below will invalidate the "products" cache tag, 
            causing the product list to be re-fetched on the next request.
          </p>
          <form action={invalidateProducts}>
            <button 
              type="submit"
              className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
            >
              Refresh Products (Invalidate Cache)
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

